import type { PDFDocument } from 'pdf-lib';
import { PDFName, PDFString } from 'pdf-lib';

/**
 * Standard, fully conforming sRGB v2.1 Color Profile (ISO 19005-2 compliance).
 * Size: 2,576 bytes. Verified against Ghostscript, veraPDF, and Java ICC_Profile parsers.
 */
const OFFICIAL_SRGB_ICC_BASE64 =
  '';

let cachedIccBytes: Uint8Array | null = null;

export function createSrgbIccProfileBytes(): Uint8Array {
  if (cachedIccBytes) {
    return cachedIccBytes;
  }

  if (typeof atob === 'function') {
    const binary = atob(OFFICIAL_SRGB_ICC_BASE64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    cachedIccBytes = bytes;
    return cachedIccBytes;
  }

  if (typeof Buffer !== 'undefined') {
    const buf = Buffer.from(OFFICIAL_SRGB_ICC_BASE64, 'base64');
    cachedIccBytes = new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
    return cachedIccBytes;
  }

  throw new Error('Ambiente sem suporte para decodificação base64');
}

/**
 * Injects standard ISO 19005-2 OutputIntents into the PDFDocument's Catalog.
 * Required for PDF/A validation in Colare (TCM-GO), Centi, PJe, ESAJ, veraPDF, and Adobe Acrobat Preflight.
 */
export function injectOutputIntent(pdfDoc: PDFDocument): void {
  const srgbBytes = createSrgbIccProfileBytes();

  // Create indirect ICC profile stream with 3 channels
  const iccStream = pdfDoc.context.flateStream(srgbBytes, {
    N: 3,
  });
  const iccRef = pdfDoc.context.register(iccStream);

  // Create OutputIntent dictionary conforming to GTS_PDFA1
  const outputIntentDict = pdfDoc.context.obj({
    Type: 'OutputIntent',
    S: 'GTS_PDFA1',
    OutputConditionIdentifier: PDFString.of('sRGB IEC61966-2.1'),
    RegistryName: PDFString.of('http://www.color.org'),
    Info: PDFString.of('sRGB IEC61966-2.1'),
    DestOutputProfile: iccRef,
  });

  const outputIntentRef = pdfDoc.context.register(outputIntentDict);

  // Attach to Document Catalog
  pdfDoc.catalog.set(
    PDFName.of('OutputIntents'),
    pdfDoc.context.obj([outputIntentRef])
  );
}
